package com.alsafa.native4;import android.app.*;import android.content.*;import android.os.*;import android.text.*;import android.view.*;import android.widget.*;import com.alsafa.native4.core.*;import java.util.*;
public final class SearchActivity extends Activity{private CoreDb db;private Native4Services services;private CoreProductCatalog catalog;private EditText query;private LinearLayout results;private TextView status;private Spinner scope;private CustomerInvoiceSearchStore customerInvoices;private final Handler h=new Handler(Looper.getMainLooper());private final Runnable run=this::search;
 public void onCreate(Bundle s){super.onCreate(s);setContentView(R.layout.activity_search);db=new CoreDb(this);services=new Native4Services(db,"native4-android-alpha");catalog=new CoreProductCatalog(db);customerInvoices=new CustomerInvoiceSearchStore(db);query=findViewById(R.id.globalSearch);results=findViewById(R.id.globalResults);status=findViewById(R.id.searchStatus);scope=findViewById(R.id.searchScope);scope.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"الكل","العملاء","فواتير المبيع","المنتجات","قطع الصيانة","الصيانات"}));scope.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?> p,View v,int pos,long id){search();}public void onNothingSelected(android.widget.AdapterView<?> p){}});query.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){h.removeCallbacks(run);h.postDelayed(run,325);}public void afterTextChanged(Editable e){}});Nav5.bind(this,R.id.navSearch);query.requestFocus();}
 private void search(){String q=query.getText().toString().trim();results.removeAllViews();if(q.isEmpty()){status.setText("ابدأ الكتابة للبحث");return;}int mode=scope.getSelectedItemPosition(),count=0;if(mode==0||mode==1)count+=customers(q);if(mode==0||mode==2)count+=invoices(q);if(mode==0||mode==3)count+=products(q);if(mode==0||mode==4)count+=parts(q);if(mode==0||mode==5)count+=repairs(q);status.setText("النتائج: "+count);}
 private int customers(String q){List<CustomerInvoiceSearchStore.CustomerHit> rows=customerInvoices.customers(q,30);for(CustomerInvoiceSearchStore.CustomerHit x:rows){List<CustomerInvoiceSearchStore.InvoiceHit> inv=customerInvoices.invoicesForCustomer(x,5);StringBuilder s=new StringBuilder("👤 ").append(x.name);if(!x.phone.isEmpty())s.append(" — ").append(x.phone);s.append("\nالنقاط: ").append(String.format(Locale.US,"%.0f",x.points)).append(" — آخر فواتير المبيع: ").append(inv.size());for(CustomerInvoiceSearchStore.InvoiceHit i:inv)s.append("\n• ").append(i.no).append(" — ").append(String.format(Locale.US,"%.2f",i.total)).append(" ").append(i.currency);add(s.toString(),SaleActivity.class);}return rows.size();}
 private int invoices(String q){List<CustomerInvoiceSearchStore.InvoiceHit> rows=customerInvoices.invoices(q,40);for(CustomerInvoiceSearchStore.InvoiceHit i:rows)addRecord("🧾 "+i.no+(i.customerName.isEmpty()?"":" — "+i.customerName)+(i.phone.isEmpty()?"":"\n"+i.phone)+(i.description.isEmpty()?"":"\n"+i.description)+"\n"+String.format(Locale.US,"%.2f",i.total)+" "+i.currency,"SALE",i.id);return rows.size();}
 private int products(String q){List<CoreProductCatalog.ProductHit> rows=catalog.search(q,40);for(CoreProductCatalog.ProductHit p:rows){String txt="⌚ "+p.name+(p.ref.isEmpty()?"":" — "+p.ref)+(p.barcode.isEmpty()?"":"\nباركود: "+p.barcode)+"\nالمتوفر: "+p.quantity+" — "+String.format(Locale.US,"%.2f",p.salePrice)+" "+p.currency;add(txt,SaleActivity.class);}return rows.size();}
 private int parts(String q){List<RepairPartStore.SearchResult> rows=services.repairParts.search(q,40);for(RepairPartStore.SearchResult p:rows)add("🔧 "+p.name+(p.barcode==null||p.barcode.isEmpty()?"":"\nباركود: "+p.barcode)+"\nالمتوفر: "+p.quantity+" — "+String.format(Locale.US,"%.2f",p.salePrice)+" "+p.currency,DirectPartSaleActivity.class);return rows.size();}
 private int repairs(String q){List<CustomerInvoiceSearchStore.RepairHit> rows=customerInvoices.repairs(q,40);for(CustomerInvoiceSearchStore.RepairHit r:rows)addRecord("🛠 "+r.no+(r.customer.isEmpty()?"":" — "+r.customer)+"\n"+r.watch+(r.phone.isEmpty()?"":"\n"+r.phone)+" — "+r.status+" — "+String.format(Locale.US,"%.2f",r.total)+" "+r.currency,"REPAIR",r.id);return rows.size();}
 private void addRecord(String text,String type,String id){TextView t=new TextView(this);t.setGravity(Gravity.END);t.setPadding(dp(12),dp(12),dp(12),dp(12));t.setBackgroundResource(R.drawable.alsafa_card);t.setText(text);t.setOnClickListener(v->{Intent i=new Intent(this,RecordDetailActivity.class);i.putExtra("record_type",type);i.putExtra("record_id",id);startActivity(i);});LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT);lp.setMargins(0,dp(5),0,dp(5));results.addView(t,lp);}
 private void add(String text,Class<?> target){TextView t=new TextView(this);t.setGravity(Gravity.END);t.setPadding(dp(12),dp(12),dp(12),dp(12));t.setBackgroundResource(R.drawable.alsafa_card);t.setText(text);t.setOnClickListener(v->startActivity(new Intent(this,target)));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT);lp.setMargins(0,dp(5),0,dp(5));results.addView(t,lp);}
 private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}@Override protected void onDestroy(){h.removeCallbacks(run);super.onDestroy();}}